import{_ as l,a0 as t,w as o,s as c,I as a,x as n,a1 as i,A as e,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"使用 Lynis 掃描 Linux 安全性 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Lynis 掃描 Linux 安全性 | LCTT (202010) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Lynis 掃描 Linux 安全性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Lynis 掃描 Linux 安全性 | LCTT (202010) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202010/20200512 Scan your Linux security with Lynis","title":"使用 Lynis 掃描 Linux 安全性","tag":"202010","desc":""},"relativePath":"202010/20200512 Scan your Linux security with Lynis.md","filePath":"[post].md"}'),d={name:"202010/20200512 Scan your Linux security with Lynis.md"};function g(h,s,u,k,y,b){const p=t("Link");return o(),c("div",null,[s[18]||(s[18]=a("h1",{id:"使用-lynis-掃描-linux-安全性",tabindex:"-1"},[n("使用 Lynis 掃描 Linux 安全性 "),a("a",{class:"header-anchor",href:"#使用-lynis-掃描-linux-安全性","aria-label":"Permalink to “使用 Lynis 掃描 Linux 安全性”"},"​")],-1)),s[19]||(s[19]=a("blockquote",null,[a("p",null,"使用這個全面的開源安全審計工具檢查你的 Linux 機器的安全性。")],-1)),s[20]||(s[20]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202010/08/095516k6bdgeb6jhiajutm.jpg",alt:""})],-1)),s[21]||(s[21]=a("p",null,"你有沒有想過你的 Linux 機器到底安全不安全？Linux 發行版眾多，每個發行版都有自己的默認設置，你在上面運行着幾十個版本各異的軟件包，還有眾多的服務在後台運行，而我們幾乎不知道或不關心這些。",-1)),s[22]||(s[22]=a("p",null,"要想確定安全態勢（指你的 Linux 機器上運行的軟件、網絡和服務的整體安全狀態），你可以運行幾個命令，得到一些零碎的相關信息，但你需要解析的數據量是巨大的。",-1)),a("p",null,[s[1]||(s[1]=n("如果能運行一個工具，生成一份關於機器安全狀況的報告，那就好得多了。而幸運的是，有一個這樣的軟件：",-1)),i(p,{href:"https://github.com/CISOfy/lynis"},{default:e(()=>[...s[0]||(s[0]=[n("Lynis",-1)])]),_:1}),s[2]||(s[2]=n("。它是一個非常流行的開源安全審計工具，可以幫助強化基於 Linux 和 Unix 的系統。根據該項目的介紹：",-1))]),s[23]||(s[23]=r(`<blockquote><p>“它運行在系統本身，可以進行深入的安全掃描。主要目標是測試安全防禦措施，並提供進一步強化系統的提示。它還將掃描一般系統信息、易受攻擊的軟件包和可能的配置問題。Lynis 常被系統管理員和審計人員用來評估其系統的安全防禦。”</p></blockquote><h3 id="安裝-lynis" tabindex="-1">安裝 Lynis <a class="header-anchor" href="#安裝-lynis" aria-label="Permalink to “安裝 Lynis”">​</a></h3><p>你的 Linux 軟件倉庫中可能有 Lynis。如果有的話，你可以用以下方法安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dnf install lynis</span></span></code></pre></div><p>或</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apt install lynis</span></span></code></pre></div><p>然而，如果你的倉庫中的版本不是最新的，你最好從 GitHub 上安裝它。（我使用的是 Red Hat Linux 系統，但你可以在任何 Linux 發行版上運行它）。就像所有的工具一樣，先在虛擬機上試一試是有意義的。要從 GitHub 上安裝它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/redhat-release</span></span>
<span class="line"><span>Red Hat Enterprise Linux Server release 7.8 (Maipo)</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ uname  -r</span></span>
<span class="line"><span>3.10.0-1127.el7.x86_64</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ git clone https://github.com/CISOfy/lynis.git</span></span>
<span class="line"><span>Cloning into &#39;lynis&#39;...</span></span>
<span class="line"><span>remote: Enumerating objects: 30, done.</span></span>
<span class="line"><span>remote: Counting objects: 100% (30/30), done.</span></span>
<span class="line"><span>remote: Compressing objects: 100% (30/30), done.</span></span>
<span class="line"><span>remote: Total 12566 (delta 15), reused 8 (delta 0), pack-reused 12536</span></span>
<span class="line"><span>Receiving objects: 100% (12566/12566), 6.36 MiB | 911.00 KiB/s, done.</span></span>
<span class="line"><span>Resolving deltas: 100% (9264/9264), done.</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>一旦你克隆了這個版本庫，那麼進入該目錄，看看裏面有什麼可用的。主要的工具在一個叫 <code>lynis</code> 的文件裏。它實際上是一個 shell 腳本，所以你可以打開它看看它在做什麼。事實上，Lynis 主要是用 shell 腳本來實現的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd lynis/</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>CHANGELOG.md        CONTRIBUTING.md  db           developer.prf  FAQ             include  LICENSE  lynis.8  README     SECURITY.md</span></span>
<span class="line"><span>CODE_OF_CONDUCT.md  CONTRIBUTORS.md  default.prf  extras         HAPPY_USERS.md  INSTALL  lynis    plugins  README.md</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ file lynis</span></span>
<span class="line"><span>lynis: POSIX shell script, ASCII text executable, with very long lines</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="運行-lynis" tabindex="-1">運行 Lynis <a class="header-anchor" href="#運行-lynis" aria-label="Permalink to “運行 Lynis”">​</a></h3><p>通過給 Lynis 一個 <code>-h</code> 選項來查看幫助部分，以便有個大概瞭解：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./lynis -h</span></span></code></pre></div><p>你會看到一個簡短的信息屏幕，然後是 Lynis 支持的所有子命令。</p><p>接下來，嘗試一些測試命令以大致熟悉一下。要查看你正在使用的 Lynis 版本，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./lynis show version</span></span>
<span class="line"><span>3.0.0</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>要查看 Lynis 中所有可用的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./lynis show commands</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Commands:</span></span>
<span class="line"><span>lynis audit</span></span>
<span class="line"><span>lynis configure</span></span>
<span class="line"><span>lynis generate</span></span>
<span class="line"><span>lynis show</span></span>
<span class="line"><span>lynis update</span></span>
<span class="line"><span>lynis upload-only</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="審計-linux-系統" tabindex="-1">審計 Linux 系統 <a class="header-anchor" href="#審計-linux-系統" aria-label="Permalink to “審計 Linux 系統”">​</a></h3><p>要審計你的系統的安全態勢，運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./lynis audit system</span></span></code></pre></div><p>這個命令運行得很快，並會返回一份詳細的報告，輸出結果可能一開始看起來很嚇人，但我將在下面引導你來閲讀它。這個命令的輸出也會被保存到一個日誌文件中，所以你可以隨時回過頭來檢查任何可能感興趣的東西。</p><p>Lynis 將日誌保存在這裏：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  Files:</span></span>
<span class="line"><span>  - Test and debug information      : /var/log/lynis.log</span></span>
<span class="line"><span>  - Report data                     : /var/log/lynis-report.dat</span></span></code></pre></div><p>你可以驗證是否創建了日誌文件。它確實創建了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /var/log/lynis.log</span></span>
<span class="line"><span>-rw-r-----. 1 root root 341489 Apr 30 05:52 /var/log/lynis.log</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ ls -l /var/log/lynis-report.dat</span></span>
<span class="line"><span>-rw-r-----. 1 root root 638 Apr 30 05:55 /var/log/lynis-report.dat</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="探索報告" tabindex="-1">探索報告 <a class="header-anchor" href="#探索報告" aria-label="Permalink to “探索報告”">​</a></h3><p>Lynis 提供了相當全面的報告，所以我將介紹一些重要的部分。作為初始化的一部分，Lynis 做的第一件事就是找出機器上運行的操作系統的完整信息。之後是檢查是否安裝了什麼系統工具和插件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[+] Initializing program</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span>  - Detecting OS...                                           [ DONE ]</span></span>
<span class="line"><span>  - Checking profiles...                                      [ DONE ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  ---------------------------------------------------</span></span>
<span class="line"><span>  Program version:           3.0.0</span></span>
<span class="line"><span>  Operating system:          Linux</span></span>
<span class="line"><span>  Operating system name:     Red Hat Enterprise Linux Server 7.8 (Maipo)</span></span>
<span class="line"><span>  Operating system version:  7.8</span></span>
<span class="line"><span>  Kernel version:            3.10.0</span></span>
<span class="line"><span>  Hardware platform:         x86_64</span></span>
<span class="line"><span>  Hostname:                  example</span></span>
<span class="line"><span>  ---------------------------------------------------</span></span>
<span class="line"><span>&lt;&lt;截斷&gt;&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[+] System Tools</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span>  - Scanning available tools...</span></span>
<span class="line"><span>  - Checking system binaries...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[+] Plugins (phase 1)</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span> Note: plugins have more extensive tests and may take several minutes to complete</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>  - Plugin: pam</span></span>
<span class="line"><span>    [..]</span></span>
<span class="line"><span>  - Plugin: systemd</span></span>
<span class="line"><span>    [................]</span></span></code></pre></div><p>接下來，該報告被分為不同的部分，每個部分都以 <code>[+]</code> 符號開頭。下面可以看到部分章節。（哇，要審核的地方有這麼多，Lynis 是最合適的工具！）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[+] Boot and services</span></span>
<span class="line"><span>[+] Kernel</span></span>
<span class="line"><span>[+] Memory and Processes</span></span>
<span class="line"><span>[+] Users, Groups and Authentication</span></span>
<span class="line"><span>[+] Shells</span></span>
<span class="line"><span>[+] File systems</span></span>
<span class="line"><span>[+] USB Devices</span></span>
<span class="line"><span>[+] Storage</span></span>
<span class="line"><span>[+] NFS</span></span>
<span class="line"><span>[+] Name services</span></span>
<span class="line"><span>[+] Ports and packages</span></span>
<span class="line"><span>[+] Networking</span></span>
<span class="line"><span>[+] Printers and Spools</span></span>
<span class="line"><span>[+] Software: e-mail and messaging</span></span>
<span class="line"><span>[+] Software: firewalls</span></span>
<span class="line"><span>[+] Software: webserver</span></span>
<span class="line"><span>[+] SSH Support</span></span>
<span class="line"><span>[+] SNMP Support</span></span>
<span class="line"><span>[+] Databases</span></span>
<span class="line"><span>[+] LDAP Services</span></span>
<span class="line"><span>[+] PHP</span></span>
<span class="line"><span>[+] Squid Support</span></span>
<span class="line"><span>[+] Logging and files</span></span>
<span class="line"><span>[+] Insecure services</span></span>
<span class="line"><span>[+] Banners and identification</span></span>
<span class="line"><span>[+] Scheduled tasks</span></span>
<span class="line"><span>[+] Accounting</span></span>
<span class="line"><span>[+] Time and Synchronization</span></span>
<span class="line"><span>[+] Cryptography</span></span>
<span class="line"><span>[+] Virtualization</span></span>
<span class="line"><span>[+] Containers</span></span>
<span class="line"><span>[+] Security frameworks</span></span>
<span class="line"><span>[+] Software: file integrity</span></span>
<span class="line"><span>[+] Software: System tooling</span></span>
<span class="line"><span>[+] Software: Malware</span></span>
<span class="line"><span>[+] File Permissions</span></span>
<span class="line"><span>[+] Home directories</span></span>
<span class="line"><span>[+] Kernel Hardening</span></span>
<span class="line"><span>[+] Hardening</span></span>
<span class="line"><span>[+] Custom tests</span></span></code></pre></div><p>Lynis 使用顏色編碼使報告更容易解讀。</p><ul><li>綠色。一切正常</li><li>黃色。跳過、未找到，可能有個建議</li><li>紅色。你可能需要仔細看看這個</li></ul><p>在我的案例中，大部分的紅色標記都是在 “Kernel Hardening” 部分找到的。內核有各種可調整的設置，它們定義了內核的功能，其中一些可調整的設置可能有其安全場景。發行版可能因為各種原因沒有默認設置這些，但是你應該檢查每一項，看看你是否需要根據你的安全態勢來改變它的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[+] Kernel Hardening</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span>  - Comparing sysctl key pairs with scan profile</span></span>
<span class="line"><span>    - fs.protected_hardlinks (exp: 1)                         [ OK ]</span></span>
<span class="line"><span>    - fs.protected_symlinks (exp: 1)                          [ OK ]</span></span>
<span class="line"><span>    - fs.suid_dumpable (exp: 0)                               [ OK ]</span></span>
<span class="line"><span>    - kernel.core_uses_pid (exp: 1)                           [ OK ]</span></span>
<span class="line"><span>    - kernel.ctrl-alt-del (exp: 0)                            [ OK ]</span></span>
<span class="line"><span>    - kernel.dmesg_restrict (exp: 1)                          [ DIFFERENT ]</span></span>
<span class="line"><span>    - kernel.kptr_restrict (exp: 2)                           [ DIFFERENT ]</span></span>
<span class="line"><span>    - kernel.randomize_va_space (exp: 2)                      [ OK ]</span></span>
<span class="line"><span>    - kernel.sysrq (exp: 0)                                   [ DIFFERENT ]</span></span>
<span class="line"><span>    - kernel.yama.ptrace_scope (exp: 1 2 3)                   [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.accept_redirects (exp: 0)             [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.accept_source_route (exp: 0)          [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.bootp_relay (exp: 0)                  [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.forwarding (exp: 0)                   [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.log_martians (exp: 1)                 [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.mc_forwarding (exp: 0)                [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.proxy_arp (exp: 0)                    [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.rp_filter (exp: 1)                    [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.all.send_redirects (exp: 0)               [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv4.conf.default.accept_redirects (exp: 0)         [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv4.conf.default.accept_source_route (exp: 0)      [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.conf.default.log_martians (exp: 1)             [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv4.icmp_echo_ignore_broadcasts (exp: 1)           [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.icmp_ignore_bogus_error_responses (exp: 1)     [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.tcp_syncookies (exp: 1)                        [ OK ]</span></span>
<span class="line"><span>    - net.ipv4.tcp_timestamps (exp: 0 1)                      [ OK ]</span></span>
<span class="line"><span>    - net.ipv6.conf.all.accept_redirects (exp: 0)             [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv6.conf.all.accept_source_route (exp: 0)          [ OK ]</span></span>
<span class="line"><span>    - net.ipv6.conf.default.accept_redirects (exp: 0)         [ DIFFERENT ]</span></span>
<span class="line"><span>    - net.ipv6.conf.default.accept_source_route (exp: 0)      [ OK ]</span></span></code></pre></div><p>看看 SSH 這個例子，因為它是一個需要保證安全的關鍵領域。這裏沒有什麼紅色的東西，但是 Lynis 對我的環境給出了很多強化 SSH 服務的建議：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[+] SSH Support</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span>  - Checking running SSH daemon                               [ FOUND ]</span></span>
<span class="line"><span>    - Searching SSH configuration                             [ FOUND ]</span></span>
<span class="line"><span>    - OpenSSH option: AllowTcpForwarding                      [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: ClientAliveCountMax                     [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: ClientAliveInterval                     [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: Compression                             [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: FingerprintHash                         [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: GatewayPorts                            [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: IgnoreRhosts                            [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: LoginGraceTime                          [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: LogLevel                                [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: MaxAuthTries                            [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: MaxSessions                             [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: PermitRootLogin                         [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: PermitUserEnvironment                   [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: PermitTunnel                            [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: Port                                    [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: PrintLastLog                            [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: StrictModes                             [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: TCPKeepAlive                            [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: UseDNS                                  [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: X11Forwarding                           [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: AllowAgentForwarding                    [ SUGGESTION ]</span></span>
<span class="line"><span>    - OpenSSH option: UsePrivilegeSeparation                  [ OK ]</span></span>
<span class="line"><span>    - OpenSSH option: AllowUsers                              [ NOT FOUND ]</span></span>
<span class="line"><span>    - OpenSSH option: AllowGroups                             [ NOT FOUND ]</span></span></code></pre></div><p>我的系統上沒有運行虛擬機或容器，所以這些顯示的結果是空的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[+] Virtualization</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[+] Containers</span></span>
<span class="line"><span>------------------------------------</span></span></code></pre></div><p>Lynis 會檢查一些從安全角度看很重要的文件的文件權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[+] File Permissions</span></span>
<span class="line"><span>------------------------------------</span></span>
<span class="line"><span>  - Starting file permissions check</span></span>
<span class="line"><span>    File: /boot/grub2/grub.cfg                                [ SUGGESTION ]</span></span>
<span class="line"><span>    File: /etc/cron.deny                                      [ OK ]</span></span>
<span class="line"><span>    File: /etc/crontab                                        [ SUGGESTION ]</span></span>
<span class="line"><span>    File: /etc/group                                          [ OK ]</span></span>
<span class="line"><span>    File: /etc/group-                                         [ OK ]</span></span>
<span class="line"><span>    File: /etc/hosts.allow                                    [ OK ]</span></span>
<span class="line"><span>    File: /etc/hosts.deny                                     [ OK ]</span></span>
<span class="line"><span>    File: /etc/issue                                          [ OK ]</span></span>
<span class="line"><span>    File: /etc/issue.net                                      [ OK ]</span></span>
<span class="line"><span>    File: /etc/motd                                           [ OK ]</span></span>
<span class="line"><span>    File: /etc/passwd                                         [ OK ]</span></span>
<span class="line"><span>    File: /etc/passwd-                                        [ OK ]</span></span>
<span class="line"><span>    File: /etc/ssh/sshd_config                                [ OK ]</span></span>
<span class="line"><span>    Directory: /root/.ssh                                     [ SUGGESTION ]</span></span>
<span class="line"><span>    Directory: /etc/cron.d                                    [ SUGGESTION ]</span></span>
<span class="line"><span>    Directory: /etc/cron.daily                                [ SUGGESTION ]</span></span>
<span class="line"><span>    Directory: /etc/cron.hourly                               [ SUGGESTION ]</span></span>
<span class="line"><span>    Directory: /etc/cron.weekly                               [ SUGGESTION ]</span></span>
<span class="line"><span>    Directory: /etc/cron.monthly                              [ SUGGESTION ]</span></span></code></pre></div><p>在報告的底部，Lynis 根據報告的發現提出了建議。每項建議後面都有一個 “TEST-ID”（為了下一部分方便，請將其保存起來）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> Suggestions (47):</span></span>
<span class="line"><span>  ----------------------------</span></span>
<span class="line"><span>  * If not required, consider explicit disabling of core dump in /etc/security/limits.conf file [KRNL-5820]</span></span>
<span class="line"><span>      https://cisofy.com/lynis/controls/KRNL-5820/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  * Check PAM configuration, add rounds if applicable and expire passwords to encrypt with new values [AUTH-9229]</span></span>
<span class="line"><span>      https://cisofy.com/lynis/controls/AUTH-9229/</span></span></code></pre></div><p>Lynis 提供了一個選項來查找關於每個建議的更多信息，你可以使用 <code>show details</code> 命令和 TEST-ID 號來訪問：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./lynis show details TEST-ID</span></span></code></pre></div><p>這將顯示該測試的其他信息。例如，我檢查了 SSH-7408 的詳細信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./lynis show details SSH-7408</span></span>
<span class="line"><span>2020-04-30 05:52:23 Performing test ID SSH-7408 (Check SSH specific defined options)</span></span>
<span class="line"><span>2020-04-30 05:52:23 Test: Checking specific defined options in /tmp/lynis.k8JwazmKc6</span></span>
<span class="line"><span>2020-04-30 05:52:23 Result: added additional options for OpenSSH &amp;lt; 7.5</span></span>
<span class="line"><span>2020-04-30 05:52:23 Test: Checking AllowTcpForwarding in /tmp/lynis.k8JwazmKc6</span></span>
<span class="line"><span>2020-04-30 05:52:23 Result: Option AllowTcpForwarding found</span></span>
<span class="line"><span>2020-04-30 05:52:23 Result: Option AllowTcpForwarding value is YES</span></span>
<span class="line"><span>2020-04-30 05:52:23 Result: OpenSSH option AllowTcpForwarding is in a weak configuration state and should be fixed</span></span>
<span class="line"><span>2020-04-30 05:52:23 Suggestion: Consider hardening SSH configuration [test:SSH-7408] [details:AllowTcpForwarding (set YES to NO)] [solution:-]</span></span></code></pre></div><h3 id="試試吧" tabindex="-1">試試吧 <a class="header-anchor" href="#試試吧" aria-label="Permalink to “試試吧”">​</a></h3><p>如果你想更多地瞭解你的 Linux 機器的安全性，請試試 Lynis。如果你想了解 Lynis 是如何工作的，可以研究一下它的 shell 腳本，看看它是如何收集這些信息的。</p><hr>`,50)),a("p",null,[s[4]||(s[4]=n("via: ",-1)),i(p,{href:"https://opensource.com/article/20/5/linux-security-lynis"},{default:e(()=>[...s[3]||(s[3]=[n("https://opensource.com/article/20/5/linux-security-lynis",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=n("作者：",-1)),i(p,{href:"https://opensource.com/users/gkamathe"},{default:e(()=>[...s[5]||(s[5]=[n("Gaurav Kamathe",-1)])]),_:1}),s[10]||(s[10]=n(" 選題：",-1)),i(p,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[6]||(s[6]=[n("lujun9972",-1)])]),_:1}),s[11]||(s[11]=n(" 譯者：",-1)),i(p,{href:"https://github.com/wxy"},{default:e(()=>[...s[7]||(s[7]=[n("wxy",-1)])]),_:1}),s[12]||(s[12]=n(" 校對：",-1)),i(p,{href:"https://github.com/wxy"},{default:e(()=>[...s[8]||(s[8]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=n("本文由 ",-1)),i(p,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原創編譯，",-1)),i(p,{href:"https://linux.cn/"},{default:e(()=>[...s[14]||(s[14]=[n("Linux中國",-1)])]),_:1}),s[17]||(s[17]=n(" 榮譽推出",-1))])])}const x=l(d,[["render",g]]);export{m as __pageData,x as default};
